from flask import current_app

from app.config import OPENAI_MODEL
from app.extensions import openai_client


def _sanitize_menu_text(text):
    import re as _re
    if not text:
        return ""
    # Mojibake onarımı: UTF-8 baytları latin-1 sanılarak çözülmüş metin (Google
    # Drive/OCR menü metninde sık görülür). Eski elle-yazılı eşleme tablosu çakışan
    # sözlük anahtarları yüzünden 12 girdinin ~8'ine çöküyor ve Türkçe küçük harf
    # onarımlarını kaybediyordu (A1). Yerine guard'lı latin-1→utf-8 round-trip:
    # gerçek mojibake'yi onarır, zaten temiz Türkçe metni (ı/ş/ğ latin-1'e
    # kodlanamaz → hata) ya da geçersiz UTF-8 üretecek metni olduğu gibi bırakır.
    if any(marker in text for marker in ('Ã', 'Ä', 'Å', 'Â')):
        try:
            text = text.encode('latin-1').decode('utf-8')
        except (UnicodeEncodeError, UnicodeDecodeError):
            pass
    text = _re.sub(r'[^\S\n]+', ' ', text)
    text = _re.sub(r' {2,}', ' ', text)
    text = _re.sub(r'(\n\s*){3,}', '\n\n', text)
    lines = []
    for line in text.split('\n'):
        stripped = line.strip()
        if stripped:
            lines.append(stripped)
        elif lines and lines[-1] != '':
            lines.append('')
    return '\n'.join(lines).strip()


def _extract_text_from_pdf(pdf_bytes):
    import pdfplumber
    import io

    try:
        pdf = pdfplumber.open(io.BytesIO(pdf_bytes))
    except Exception as e:
        err_str = str(e).lower()
        if "password" in err_str or "encrypt" in err_str:
            raise ValueError("PDF_ENCRYPTED")
        raise ValueError(f"PDF_CORRUPT: {type(e).__name__}")

    text_parts = []
    scanned_pages = []

    try:
        for idx, page in enumerate(pdf.pages[:20]):
            page_text = page.extract_text(x_tolerance=2, y_tolerance=3) or ""

            tables = page.extract_tables() or []
            table_text_parts = []
            for table in tables:
                for row in table:
                    cells = [str(c).strip() for c in row if c is not None and str(c).strip()]
                    if cells:
                        table_text_parts.append(" | ".join(cells))
            table_text = "\n".join(table_text_parts)

            combined = (page_text + "\n" + table_text).strip()

            if len(combined.replace(" ", "").replace("\n", "")) < 10:
                scanned_pages.append(idx)
            else:
                text_parts.append(combined)
    finally:
        pdf.close()

    text_result = "\n\n".join(text_parts)

    if scanned_pages and len(text_result.strip()) < 50:
        current_app.logger.info(f"[PDF] Scanned PDF detected: {len(scanned_pages)} pages with no text, forwarding to Vision OCR")
        ocr_text = _extract_pdf_pages_via_vision(pdf_bytes, scanned_pages[:5])
        if ocr_text:
            text_result = (text_result + "\n\n" + ocr_text).strip() if text_result.strip() else ocr_text
    elif scanned_pages:
        current_app.logger.info(f"[PDF] {len(scanned_pages)} scanned pages skipped (text pages had sufficient content)")

    return _sanitize_menu_text(text_result)


def _extract_pdf_pages_via_vision(pdf_bytes, page_indices):
    import io
    try:
        import pdfplumber
        pdf = pdfplumber.open(io.BytesIO(pdf_bytes))
    except Exception:
        return ""

    results = []
    try:
        for idx in page_indices:
            if idx >= len(pdf.pages):
                continue
            page = pdf.pages[idx]
            try:
                img = page.to_image(resolution=200)
                img_buffer = io.BytesIO()
                img.original.save(img_buffer, format="PNG")
                img_bytes = img_buffer.getvalue()
                current_app.logger.info(f"[PDF→OCR] Page {idx + 1}: rendered {len(img_bytes)} bytes")
                text = _extract_text_from_image(img_bytes, "image/png")
                if text:
                    results.append(f"[Sayfa {idx + 1}]\n{text}")
            except Exception as e:
                current_app.logger.warning(f"[PDF→OCR] Page {idx + 1} render failed: {type(e).__name__}: {e}")
                continue
    finally:
        pdf.close()

    return "\n\n".join(results)


def _compress_image_for_vision(image_bytes, max_bytes=1_500_000):
    from PIL import Image
    import io

    try:
        img = Image.open(io.BytesIO(image_bytes))
    except Exception:
        return image_bytes, "image/jpeg"

    if img.mode in ("RGBA", "P"):
        img = img.convert("RGB")

    max_dim = 1600
    if max(img.size) > max_dim:
        ratio = max_dim / max(img.size)
        img = img.resize((int(img.width * ratio), int(img.height * ratio)), Image.LANCZOS)

    buf = io.BytesIO()
    quality = 85
    img.save(buf, format="JPEG", quality=quality)
    while buf.tell() > max_bytes and quality > 30:
        quality -= 15
        buf = io.BytesIO()
        img.save(buf, format="JPEG", quality=quality)

    current_app.logger.info(f"[VISION] Compressed image: {len(image_bytes)} -> {buf.tell()} bytes (q={quality}, {img.size[0]}x{img.size[1]})")
    return buf.getvalue(), "image/jpeg"


def _extract_text_from_image(image_bytes, content_type="image/jpeg"):
    import base64

    if len(image_bytes) > 1_500_000:
        image_bytes, content_type = _compress_image_for_vision(image_bytes)

    b64 = base64.b64encode(image_bytes).decode("utf-8")
    mime = content_type.split(";")[0].strip()
    if mime not in ("image/jpeg", "image/png", "image/webp", "image/gif"):
        mime = "image/jpeg"

    vision_system = (
        "Sen bir restoran menüsü OCR asistanısın. Görseldeki TÜM yemek ve içecek isimlerini, "
        "açıklamalarını ve fiyatlarını eksiksiz oku. Hiçbir öğeyi atlama veya özetleme. "
        "Menüdeki kategori başlıklarını koru (örn: Kahvaltılar, Salatalar, Ana Yemekler). "
        "Her yemeği ayrı satırda yaz. Türkçe karakterleri doğru kullan (ı, ş, ğ, ç, ö, ü)."
    )
    try:
        resp = openai_client.chat.completions.create(
            model=OPENAI_MODEL,
            # L5: çıktı 4000 token ile sınırlı (uzun menülerin tam OCR'ı için
            # gerekli) ve girdi görseli >1.5MB ise üstte sıkıştırılıyor. Asıl
            # maliyet guard'ı çağıran rotalardaki rate-limit (SCRAPE_RATELIMIT) +
            # genel AI maliyet kontrolleridir (H2 girdi-cap, M4 sohbet kotası).
            max_tokens=4000,
            temperature=0.0,
            messages=[
                {"role": "system", "content": vision_system},
                {"role": "user", "content": [
                    {"type": "text", "text": (
                        "Bu restoran menüsü görselindeki TÜM yemek ve içecek isimlerini satır satır oku. "
                        "Kategori başlıklarını koru. Hiçbir öğeyi atlama, özetleme veya yorum ekleme. "
                        "Sadece menüde yazanları aynen oku."
                    )},
                    {"type": "image_url", "image_url": {"url": f"data:{mime};base64,{b64}"}},
                ]},
            ],
        )
        # İçerik filtresi/boş yanıtta choices boş gelebilir — _openai_chat'teki
        # aynı korumayı buraya da koy ki resp.choices[0] IndexError fırlatmasın (A2).
        if not resp.choices:
            current_app.logger.warning("[VISION OCR] Boş choices (içerik filtresi olabilir) — boş metin döndürülüyor")
            return ""
        result = (resp.choices[0].message.content or "").strip()
        current_app.logger.info(f"[VISION OCR] Extracted {len(result)} chars")
        return result
    except Exception as e:
        current_app.logger.warning(f"[VISION OCR] Failed: {type(e).__name__}: {e}")
        return ""
